{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "Ensure S3 bucket has block public ACLs enabled",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "MEDIUM",
      "explanation": "The 'block_public_acls' attribute is missing in the aws_s3_bucket_public_access_block resource. Without this, public ACLs could be applied to the bucket, potentially exposing sensitive data."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket = aws_s3_bucket.document_storage.id\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n  block_public_acls       = true\n}",
  "fix_summary": "Added the 'block_public_acls' attribute to the aws_s3_bucket_public_access_block resource to ensure public ACLs are blocked, mitigating the risk of unintended public access."
}
